\title{Positive-Term, Integral, and Sandwich Representations of the\\
Euler--Mascheroni Constant, with the Structural Obstruction to Irrationality}
\author{Aristotle}
\date{2026-06-24}

\begin{document}
\maketitle

\begin{abstract}
The Euler--Mascheroni constant $\gamma = \lim_{n\to\infty}(H_n - \ln n)$ is among the most studied constants in mathematics, yet whether it is rational or irrational remains unknown. This paper develops three exact and mutually reinforcing representations of $\gamma$ and uses them to make precise the structural obstruction to an irrationality proof. First, we exhibit $\gamma$ as a convergent series of \emph{strictly positive} terms, $\gamma = \sum_{k\ge 0}\big(\tfrac{1}{k+1} - \ln\tfrac{k+2}{k+1}\big)$, whose $n$-th partial sum equals exactly the classical lower approximant $\ell_n = H_n - \ln(n+1)$; consequently $\ell_n$ is strictly increasing. Second, we realize each term as a unit-interval integral, yielding $\gamma = \sum_{k\ge 0}\int_{k+1}^{k+2}\big(\tfrac{1}{k+1} - \tfrac{1}{x}\big)dx$, the term-by-term form of $\gamma = \int_1^\infty\big(\tfrac{1}{\lfloor x\rfloor} - \tfrac1x\big)dx$. Third, we record the two-sided sandwich $\ell_n < \gamma < u_n$ with $u_n = H_n - \ln n$ and the \emph{exact} trap width $u_n - \ell_n = \ln(1 + 1/n)$, giving fully effective error bounds. Finally, we connect these representations to an irrationality criterion: $\gamma$ is irrational if and only if arbitrarily small nonzero integer linear forms $q\gamma - p$ exist (a consequence of Dirichlet's approximation theorem). We argue that all natural approximants produced by our representations are rational numbers contaminated by a transcendental logarithm, and that this non-rationality is the genuine obstruction. All results have been formally verified.
\end{abstract}

\textbf{Keywords:} Euler--Mascheroni constant, harmonic numbers, positive-term series, integral representation, telescoping, irrationality, Dirichlet approximation, Stieltjes constants.

\section{Introduction}

The harmonic numbers $H_n = \sum_{k=1}^{n} \tfrac1k$ diverge logarithmically: $H_n = \ln n + \gamma + o(1)$, where
\[
\gamma = \lim_{n\to\infty}\big(H_n - \ln n\big) = 0.57721566490153286\ldots
\]
is the \emph{Euler--Mascheroni constant}. Despite three centuries of study, it is not known whether $\gamma \in \mathbb{Q}$. This contrasts with $e$ (Euler) and $\zeta(3)$ (Ap\'ery, 1978), both known irrational through explicit, fast rational approximation schemes.

We collect and prove, in a unified elementary way, three exact representations of $\gamma$: a positive-term series, an integral form, and a two-sided sandwich with explicit width. We then use these to articulate, and prove an equivalent criterion for, the precise structural reason an irrationality proof remains out of reach: every approximant our representations supply is a rational harmonic number perturbed by a transcendental logarithm, and that perturbation defeats the standard machinery. All statements correspond to formally verified theorems; we give proof sketches.

\paragraph{Notation.} $H_n = \sum_{k=1}^n \tfrac1k$ is the $n$-th harmonic number ($H_0 = 0$); $\ln$ is the natural logarithm; $\lfloor x\rfloor$ is the floor function. The two one-sided approximant sequences are
\[
\ell_n = H_n - \ln(n+1), \qquad u_n = H_n - \ln n \quad (n\ge 1),
\]
the \emph{lower} and \emph{upper} approximants.

\section{The positive-term series}

\begin{definition}[Series term]
For $k \in \mathbb{N}$, define
\[
g_k = \frac{1}{k+1} - \big(\ln(k+2) - \ln(k+1)\big) = \frac{1}{k+1} - \ln\frac{k+2}{k+1}.
\]
\end{definition}

\begin{theorem}[\texttt{gterm\_pos}]
For every $k\in\mathbb{N}$, $g_k > 0$.
\end{theorem}
\begin{proof}[Proof sketch]
Set $x = \tfrac{k+2}{k+1} > 1$, so $x\ne1$ and $x-1 = \tfrac{1}{k+1}$. The strict tangent-line inequality $\ln x < x - 1$ for $x>0,\ x\ne1$ gives $\ln\tfrac{k+2}{k+1} < \tfrac{1}{k+1}$, hence $g_k>0$. In the formalization this is \texttt{Real.log\_lt\_sub\_one\_of\_pos}.
\end{proof}

\begin{theorem}[\texttt{gterm\_partial}]
For every $n\in\mathbb{N}$,
\[
\sum_{k=0}^{n-1} g_k = H_n - \ln(n+1) = \ell_n.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The harmonic part gives $\sum_{k=0}^{n-1}\tfrac{1}{k+1} = H_n$; the logarithmic part telescopes to $\ln(n+1) - \ln 1 = \ln(n+1)$. Formally, induction on $n$ with $H_{n+1} = H_n + \tfrac{1}{n+1}$.
\end{proof}

\begin{theorem}[\texttt{hasSum\_gterm}]
The series converges with $\sum_{k=0}^{\infty} g_k = \gamma.$
\end{theorem}
\begin{proof}[Proof sketch]
By the previous theorem the partial sums of $g$ equal $(\ell_n)_n$, which converges to $\gamma$. Since $g_k\ge0$ and the partial sums are bounded above by $\gamma$, the series is summable, and its sum equals the limit of partial sums, i.e. $\gamma$.
\end{proof}

\begin{corollary}[\texttt{strictMono\_eulerMascheroniSeq}]
$\ell_n = H_n - \ln(n+1)$ is strictly increasing, since $\ell_{n+1} - \ell_n = g_n > 0$.
\end{corollary}

A second-order expansion gives $g_k \sim \tfrac{1}{2(k+1)^2}$, so the series is summable with tail $O(1/n)$.

\section{The integral representation}

\begin{theorem}[\texttt{integrand\_nonneg}]
For $k\in\mathbb{N}$ and $x\ge k+1$, $\ \tfrac{1}{k+1} - \tfrac{1}{x} \ge 0$.
\end{theorem}
\begin{proof}[Proof sketch]
$0 < k+1 \le x$ gives $\tfrac1x \le \tfrac{1}{k+1}$ by monotonicity of reciprocal on positives.
\end{proof}

\begin{theorem}[\texttt{gterm\_eq\_integral}]
For every $k\in\mathbb{N}$,
\[
g_k = \int_{k+1}^{k+2}\left(\frac{1}{k+1} - \frac{1}{x}\right)dx.
\]
\end{theorem}
\begin{proof}[Proof sketch]
By linearity: the constant piece integrates to $\tfrac{1}{k+1}$ over a unit interval, and $\int_{k+1}^{k+2}\tfrac1x\,dx = \ln(k+2)-\ln(k+1)$ since $0\notin[k+1,k+2]$. Subtract to recover $g_k$. Formally via \texttt{intervalIntegrable\_one\_div}, \texttt{integral\_one\_div}, and \texttt{intervalIntegral.integral\_const}.
\end{proof}

\begin{theorem}[\texttt{hasSum\_integral\_repr}]
\[
\gamma = \sum_{k=0}^{\infty}\int_{k+1}^{k+2}\left(\frac{1}{k+1} - \frac{1}{x}\right)dx.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The summand equals $g_k$ pointwise; substitute into \texttt{hasSum\_gterm}.
\end{proof}

\begin{remark}[Continuous form]
Since $\lfloor x\rfloor = k+1$ on $[k+1,k+2)$, the flat-line height is $1/\lfloor x\rfloor$, and splitting $[1,\infty)$ into these windows yields $\gamma = \int_1^\infty\big(\tfrac{1}{\lfloor x\rfloor} - \tfrac1x\big)dx$, the area between the staircase $1/\lfloor x\rfloor$ and the hyperbola $1/x$.
\end{remark}

\begin{theorem}[\texttt{integral\_partialSum\_lt\_lt\_seq'}]
For every $n\in\mathbb{N}$,
\[
\sum_{k=0}^{n-1}\int_{k+1}^{k+2}\left(\frac{1}{k+1} - \frac{1}{x}\right)dx \;<\; \gamma \;<\; u_n.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The partial sum equals $\ell_n$ by the integral identity and \texttt{gterm\_partial}; combine with the sandwich $\ell_n<\gamma<u_n$.
\end{proof}

\section{The two-sided sandwich and effective bounds}

\begin{theorem}[\texttt{eulerMascheroniSeq\_sandwich}]
For every $n$, $\ \ell_n < \gamma < u_n$.
\end{theorem}
\begin{proof}[Proof sketch]
Standard library facts $\ell_n<\gamma$ and $\gamma<u_n$; the lower bound also follows from positivity of the $g_k$.
\end{proof}

\begin{theorem}[\texttt{eulerMascheroni\_trap\_width\_eq}]
For $n\ge1$, $\ u_n - \ell_n = \ln(n+1) - \ln n = \ln(1 + 1/n).$
\end{theorem}
\begin{proof}[Proof sketch]
$u_n - \ell_n = (H_n - \ln n) - (H_n - \ln(n+1))$; the harmonic terms cancel.
\end{proof}

\begin{theorem}[\texttt{eulerMascheroniConstant\_sub\_seq\_lt}, \texttt{seq'\_sub\_eulerMascheroniConstant\_lt}, \texttt{abs\_eulerMascheroniSeq\_sub\_lt}]
For $n\ge1$,
\[
0 < \gamma - \ell_n < \ln\!\Big(1+\tfrac1n\Big), \quad 0 < u_n - \gamma < \ln\!\Big(1+\tfrac1n\Big), \quad |\ell_n - \gamma| < \ln\!\Big(1+\tfrac1n\Big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Each one-sided error is strictly less than the full trap width, which equals $\ln(1+1/n)$.
\end{proof}

\begin{theorem}[\texttt{tendsto\_eulerMascheroni\_trap\_width}]
$u_n - \ell_n \to 0$ as $n\to\infty$.
\end{theorem}
\begin{proof}[Proof sketch]
The width is $\ln(1+1/n)$, which tends to $0$ by continuity of $\ln$ at $1$.
\end{proof}

The enclosure is \emph{effective} but converges only at rate $O(1/n)$.

\section{The irrationality criterion and the obstruction}

\begin{theorem}[\texttt{irrational\_iff\_forall\_eps\_linear\_form}]
A real $x$ is irrational iff for every $\varepsilon>0$ there exist $q\in\mathbb{N}_{>0}$, $p\in\mathbb{Z}$ with $0 < |qx - p| < \varepsilon$.
\end{theorem}
\begin{proof}[Proof sketch]
($\Leftarrow$) If $x=a/b$, then $qx-p$ is rational with denominator $b$, so nonzero values are $\ge 1/b$, contradicting the hypothesis at $\varepsilon=1/b$. ($\Rightarrow$) Dirichlet's approximation theorem gives infinitely many $p/q$ with $|qx-p|<1/q$, nonzero by irrationality.
\end{proof}

\begin{theorem}[\texttt{irrational\_eulerMascheroniConstant\_iff}]
$\gamma$ is irrational iff for every $\varepsilon>0$ there are $q\in\mathbb{N}_{>0}$, $p\in\mathbb{Z}$ with $0 < |q\gamma - p| < \varepsilon$.
\end{theorem}

\paragraph{The obstruction.} To feed this criterion we would need \emph{rational} approximations $p/q$. But $\ell_n = H_n - \ln(n+1)$ and $u_n = H_n - \ln n$ are not rational: each is a rational harmonic number minus a transcendental logarithm. Two deficiencies stack: (1) \emph{non-rationality} of the approximants; and (2) the \emph{slow rate} $\ln(1+1/n) = O(1/n)$, where irrationality needs width $o(1/q)$. The difficulty is not the absence of representations but the non-rational nature of the approximants they produce.

\section{The Stieltjes hierarchy}

The constant $\gamma$ is the $m=0$ member of the Stieltjes constants
\[
\gamma_m = \lim_{n\to\infty}\left(\sum_{k=1}^{n}\frac{(\ln k)^m}{k} - \frac{(\ln n)^{m+1}}{m+1}\right),
\]
the Laurent coefficients of $\zeta(s)$ about $s=1$: $\zeta(s) = \tfrac{1}{s-1} + \sum_{m\ge0}\tfrac{(-1)^m}{m!}\gamma_m (s-1)^m$. The $m=0$ case is exactly the staircase-versus-curve comparison here, since $\int\tfrac{(\ln x)^m}{x}dx = \tfrac{(\ln x)^{m+1}}{m+1}$ becomes $\int\tfrac1x dx = \ln x$. Thus $\gamma_0 = \gamma$ (\texttt{tendsto\_stieltjesSeq\_zero}).

\section{Algorithms}

\textbf{Lower approximant.} Accumulate $H_n=\sum_{k=1}^n 1/k$ and return $H_n - \ln(n+1)$; cost $O(n)$.
\textbf{Effective enclosure.} Given $\varepsilon$, pick $n>1/\varepsilon$ so $\ln(1+1/n)<\varepsilon$, return $[\ell_n,u_n]\ni\gamma$.
\textbf{Term-wise.} Summing $g_k$ reproduces $\ell_n$ while exhibiting each positive brick / window integral.

\section{Applications and discussion}

The effective bounds yield certified rigorous enclosures of $\gamma$. Averaging $\ell_n,u_n$ cancels the leading $1/n$ error, giving $O(1/n^2)$ acceleration. The irrationality equivalence pinpoints what is missing: rational, fast, controlled approximants. The $m=0$ staircase mechanism templates the entire Stieltjes hierarchy.

\section{Conclusion}

We gave three exact, elementary, formally verified representations of $\gamma$ and used them to state, and prove an equivalent criterion for, the structural obstruction to its irrationality. The constant is fully tractable to compute and enclose; what remains stubborn is its arithmetic, and we made precise that the obstruction is the non-rational nature of every approximant the representations supply.

\end{document}

