function enclose_gamma(epsilon):
    n <- ceil(1 / epsilon) + 1        # ensures log(1+1/n) < epsilon
    H <- 0
    for k = 1 to n:
        H <- H + 1/k                  # accumulate harmonic number H_n
    ell <- H - log(n + 1)             # lower approximant, ell < gamma
    u   <- H - log(n)                 # upper approximant, gamma < u
    return (ell, u)                   # certified interval, width log(1+1/n)

function averaged_gamma(n):
    H <- 0
    for k = 1 to n: H <- H + 1/k
    ell <- H - log(n + 1)
    u   <- H - log(n)
    return (ell + u) / 2          # error O(1/n^2)
